package com.google.javascript.rhino.jstype;

import com.google.common.collect.Maps;
import com.google.javascript.rhino.ErrorReporter;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.jstype.RecordTypeBuilder.RecordProperty;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.SortedMap;
import org.junit.*;
import org.junit.Test;
import org.mockito.internal.util.reflection.FieldSetter;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class RecordType_isEquivalentTo_TriageGen1Test {

    // Helper to inject properties into the RecordType via reflection to ensure coverage
    private void setProperties(RecordType target, Map<String, JSType> props) throws Exception {
        java.lang.reflect.Field field = RecordType.class.getDeclaredField("properties");
        field.setAccessible(true);
        field.set(target, props);
    }

    @Test
    public void testIsNotRecordType() {
        RecordType recordType = mock(RecordType.class);
        JSType other = mock(JSType.class);
        when(other.isRecordType()).thenReturn(false);

        assertFalse(recordType.isEquivalentTo(other));
    }

    @Test
    public void testIsSameInstance() throws Exception {
        RecordType recordType = mock(RecordType.class);
        when(recordType.isRecordType()).thenReturn(true);
        when(recordType.toMaybeRecordType()).thenReturn(recordType);

        assertTrue(recordType.isEquivalentTo(recordType));
    }

    @Test
    public void testDifferentKeySets() throws Exception {
        RecordType recordType = mock(RecordType.class);
        RecordType otherRecord = mock(RecordType.class);
        JSType other = mock(JSType.class);

        Map<String, JSType> props1 = new HashMap<>();
        props1.put("a", mock(JSType.class));

        Map<String, JSType> props2 = new HashMap<>();
        props2.put("b", mock(JSType.class));

        when(other.isRecordType()).thenReturn(true);
        when(other.toMaybeRecordType()).thenReturn(otherRecord);

        setProperties(recordType, props1);
        // We need to set the field in the mocked otherRecord
        setProperties(otherRecord, props2);

        assertFalse(recordType.isEquivalentTo(other));
    }

    @Test
    public void testDifferentPropertyValues() throws Exception {
        RecordType recordType = mock(RecordType.class);
        RecordType otherRecord = mock(RecordType.class);
        JSType other = mock(JSType.class);

        JSType type1 = mock(JSType.class);
        JSType type2 = mock(JSType.class);

        Map<String, JSType> props1 = new HashMap<>();
        props1.put("a", type1);

        Map<String, JSType> props2 = new HashMap<>();
        props2.put("a", type2);

        when(other.isRecordType()).thenReturn(true);
        when(other.toMaybeRecordType()).thenReturn(otherRecord);
        when(type2.isEquivalentTo(type1)).thenReturn(false);

        setProperties(recordType, props1);
        setProperties(otherRecord, props2);

        assertFalse(recordType.isEquivalentTo(other));
    }

    @Test
    public void testEquivalentProperties() throws Exception {
        RecordType recordType = mock(RecordType.class);
        RecordType otherRecord = mock(RecordType.class);
        JSType other = mock(JSType.class);

        JSType type1 = mock(JSType.class);
        JSType type2 = mock(JSType.class);

        Map<String, JSType> props1 = new HashMap<>();
        props1.put("a", type1);

        Map<String, JSType> props2 = new HashMap<>();
        props2.put("a", type2);

        when(other.isRecordType()).thenReturn(true);
        when(other.toMaybeRecordType()).thenReturn(otherRecord);
        when(type2.isEquivalentTo(type1)).thenReturn(true);

        setProperties(recordType, props1);
        setProperties(otherRecord, props2);

        assertTrue(recordType.isEquivalentTo(other));
    }

    @Test
    public void testEmptyProperties() throws Exception {
        RecordType recordType = mock(RecordType.class);
        RecordType otherRecord = mock(RecordType.class);
        JSType other = mock(JSType.class);

        when(other.isRecordType()).thenReturn(true);
        when(other.toMaybeRecordType()).thenReturn(otherRecord);

        setProperties(recordType, Collections.emptyMap());
        setProperties(otherRecord, Collections.emptyMap());

        assertTrue(recordType.isEquivalentTo(other));
    }
}
